1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body { margin: 0; padding: 2rem 1rem; font: 16px/1.4 system-ui, sans-serif; background: #f6f6f4; color: #222; }
10	  main { max-width: 32rem; margin: 0 auto; }
11	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
12	  form { display: flex; gap: .5rem; margin-bottom: 1rem; }
13	  input { flex: 1; padding: .5rem .75rem; font: inherit; border: 1px solid #ccc; border-radius: 6px; }
14	  button { padding: .5rem .9rem; font: inherit; border: 1px solid #bbb; border-radius: 6px; background: #fff; cursor: pointer; }
15	  button:hover { background: #eee; }
16	  ul { list-style: none; margin: 0; padding: 0; }
17	  li { display: flex; align-items: center; gap: .5rem; padding: .5rem .75rem; margin-bottom: .4rem; background: #fff; border: 1px solid #e2e2e2; border-radius: 6px; }
18	  li span { flex: 1; overflow-wrap: anywhere; }
19	  li[data-completed="true"] span { text-decoration: line-through; color: #888; }
20	  li input[type="checkbox"] { flex: none; width: 1.1rem; height: 1.1rem; margin: 0; }
21	  .filters { display: flex; gap: .5rem; margin-bottom: 1rem; }
22	  .filters button[aria-pressed="true"] { background: #222; border-color: #222; color: #fff; }
23	  form input[type="date"] { flex: none; }
24	  .due { flex: none; font-size: .85rem; color: #666; }
25	  li[data-overdue="true"] { border-color: #d33; background: #fff1f0; }
26	  li[data-overdue="true"] .due { color: #b00; font-weight: 600; }
27	  form select { flex: none; padding: .5rem; font: inherit; border: 1px solid #ccc; border-radius: 6px; background: #fff; }
28	  /* [REQ-006] Priority is shown as a neutral text label only; no per-priority colours, so the overdue highlight stays readable. */
29	  /* [REQ-007] Search box and inline edit field. */
30	  .search { display: block; width: 100%; margin-bottom: 1rem; }
31	  li input.edit { padding: .2rem .4rem; }
32	  .priority { flex: none; font-size: .75rem; font-weight: 600; text-transform: uppercase; padding: .1rem .4rem; border-radius: 4px; background: #ececec; color: #555; }
33	</style>
34	</head>
35	<body>
36	<main>
37	  <h1>Todos</h1>
38	  <form id="todo-form">
39	    <input data-testid="todo-input" type="text" placeholder="What needs doing?" aria-label="New todo" autocomplete="off">
40	    <input data-testid="todo-due" type="date" aria-label="Due date (optional)">
41	    <select data-testid="todo-priority" aria-label="Priority">
42	      <option value="low">Low</option>
43	      <option value="med" selected>Med</option>
44	      <option value="high">High</option>
45	    </select>
46	    <button data-testid="todo-add" type="submit">Add</button>
47	  </form>
48	  <input class="search" data-testid="search-input" type="search" placeholder="Search todos" aria-label="Search todos" autocomplete="off">
49	  <div class="filters" role="group" aria-label="Filter todos">
50	    <button data-testid="filter-all" type="button" data-filter="all" aria-pressed="true">All</button>
51	    <button data-testid="filter-active" type="button" data-filter="active" aria-pressed="false">Active</button>
52	    <button data-testid="filter-completed" type="button" data-filter="completed" aria-pressed="false">Completed</button>
53	  </div>
54	  <ul data-testid="todo-list"></ul>
55	</main>
56	<script>
57	  var STORAGE_KEY = 'todos';
58	  var form = document.getElementById('todo-form');
59	  var input = document.querySelector('[data-testid="todo-input"]');
60	  var dueInput = document.querySelector('[data-testid="todo-due"]');
61	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
62	  var list = document.querySelector('[data-testid="todo-list"]');
63	  var filterButtons = document.querySelectorAll('[data-filter]');
64	  var currentFilter = 'all';
65	  var searchInput = document.querySelector('[data-testid="search-input"]');
66	  var searchTerm = '';
67	
68	  // [REQ-001] Load todos from localStorage; ignore malformed data.
69	  function loadTodos() {
70	    try {
71	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
72	      if (!Array.isArray(parsed)) return [];
73	      // [REQ-002] Todos saved before completion existed default to active.
74	      parsed.forEach(function (t) {
75	        t.completed = t.completed === true;
76	        // [REQ-003] Drop anything that is not a plain YYYY-MM-DD string.
77	        t.due = normalizeDue(t.due);
78	        // [REQ-004] Todos saved before priorities existed default to med.
79	        t.priority = normalizePriority(t.priority);
80	      });
81	      return parsed;
82	    } catch (e) {
83	      return [];
84	    }
85	  }
86	
87	  // [REQ-001]
88	  function saveTodos() {
89	    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(todos)); } catch (e) {}
90	  }
91	
92	  // [REQ-001] Stable unique id; crypto.randomUUID is not available in every file:// context.
93	  function makeId() {
94	    if (window.crypto && typeof crypto.randomUUID === 'function') {
95	      try { return crypto.randomUUID(); } catch (e) {}
96	    }
97	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
98	  }
99	
100	  // [REQ-003] Due dates are plain YYYY-MM-DD strings, treated as local calendar dates. Never parsed through UTC.
101	  function normalizeDue(value) {
102	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : null;
103	  }
104	
105	  // [REQ-004] Priority is one of low, med, high; anything else becomes med.
106	  function normalizePriority(value) {
107	    return value === 'low' || value === 'high' ? value : 'med';
108	  }
109	
110	  // [REQ-003] Today's local calendar date as YYYY-MM-DD.
111	  function localToday(now) {
112	    function pad(n) { return (n < 10 ? '0' : '') + n; }
113	    return now.getFullYear() + '-' + pad(now.getMonth() + 1) + '-' + pad(now.getDate());
114	  }
115	
116	  // [REQ-003] Overdue means strictly before today's local date. Same-format strings compare correctly as text.
117	  function isOverdue(due, today) {
118	    return due !== null && due < today;
119	  }
120	
121	  // [REQ-002] [REQ-005] Ordering: active todos first, completed below (DEC-003).
122	  // Within each group: high, then med, then low; insertion order within the same priority.
123	  // The todos array is kept in insertion order; bucketing by priority is stable, so it preserves that order.
124	  function orderTodos(items) {
125	    function byPriority(group) {
126	      return ['high', 'med', 'low'].reduce(function (out, p) {
127	        return out.concat(group.filter(function (t) { return t.priority === p; }));
128	      }, []);
129	    }
130	    return byPriority(items.filter(function (t) { return !t.completed; }))
131	      .concat(byPriority(items.filter(function (t) { return t.completed; })));
132	  }
133	
134	  // [REQ-002]
135	  function matchesFilter(todo, filter) {
136	    if (filter === 'active') return !todo.completed;
137	    if (filter === 'completed') return todo.completed;
138	    return true;
139	  }
140	
141	  // [REQ-007] Case-insensitive substring match on the todo text; an empty term matches everything.
142	  function matchesSearch(todo, term) {
143	    return todo.text.toLowerCase().indexOf(term.toLowerCase()) !== -1;
144	  }
145	
146	  // [REQ-001] [REQ-002] [REQ-003] [REQ-004] [REQ-007]
147	  function render() {
148	    list.textContent = '';
149	    var today = localToday(new Date());
150	    filterButtons.forEach(function (btn) {
151	      btn.setAttribute('aria-pressed', String(btn.dataset.filter === currentFilter));
152	    });
153	    // [REQ-007] Search narrows the filtered set; both must match.
154	    orderTodos(todos).filter(function (t) { return matchesFilter(t, currentFilter) && matchesSearch(t, searchTerm); }).forEach(function (todo) {
155	      var li = document.createElement('li');
156	      li.setAttribute('data-testid', 'todo-item');
157	      li.setAttribute('data-completed', String(todo.completed));
158	      li.setAttribute('data-overdue', String(isOverdue(todo.due, today)));
159	      li.setAttribute('data-priority', todo.priority);
160	      li.dataset.id = todo.id;
161	
162	      var toggle = document.createElement('input');
163	      toggle.type = 'checkbox';
164	      toggle.setAttribute('data-testid', 'todo-toggle');
165	      toggle.checked = todo.completed;
166	      toggle.setAttribute('aria-label', 'Mark "' + todo.text + '" ' + (todo.completed ? 'incomplete' : 'complete'));
167	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
168	
169	      var text = document.createElement('span');
170	      text.setAttribute('data-testid', 'todo-text');
171	      text.textContent = todo.text;
172	      text.addEventListener('dblclick', function () { startEdit(text, todo); });
173	
174	      var del = document.createElement('button');
175	      del.type = 'button';
176	      del.setAttribute('data-testid', 'todo-delete');
177	      del.textContent = 'Delete';
178	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
179	      del.addEventListener('click', function () { deleteTodo(todo.id); });
180	
181	      li.appendChild(toggle);
182	      li.appendChild(text);
183	      var priority = document.createElement('span');
184	      priority.className = 'priority';
185	      priority.textContent = todo.priority;
186	      li.appendChild(priority);
187	      if (todo.due) {
188	        var due = document.createElement('span');
189	        due.className = 'due';
190	        due.setAttribute('data-testid', 'todo-due-date');
191	        due.textContent = 'Due ' + todo.due;
192	        li.appendChild(due);
193	      }
194	      li.appendChild(del);
195	      list.appendChild(li);
196	    });
197	  }
198	
199	  // [REQ-001] [REQ-003] [REQ-004]
200	  function addTodo(rawText, rawDue, rawPriority) {
201	    var text = rawText.trim();
202	    if (!text) return;
203	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(rawDue), priority: normalizePriority(rawPriority) });
204	    saveTodos();
205	    render();
206	  }
207	
208	  // [REQ-007] Swap the text for an input. Enter or blur commits, Escape cancels.
209	  // Blank text on commit is treated as a cancel, so editing never deletes a todo.
210	  function startEdit(textEl, todo) {
211	    var field = document.createElement('input');
212	    field.type = 'text';
213	    field.className = 'edit';
214	    field.setAttribute('data-testid', 'todo-edit-input');
215	    field.setAttribute('aria-label', 'Edit todo');
216	    field.value = todo.text;
217	    var finished = false;
218	    function finish(commit) {
219	      if (finished) return;
220	      finished = true;
221	      if (commit) editTodo(todo.id, field.value);
222	      else render();
223	    }
224	    field.addEventListener('keydown', function (e) {
225	      if (e.key === 'Enter') { e.preventDefault(); finish(true); }
226	      else if (e.key === 'Escape') { e.preventDefault(); finish(false); }
227	    });
228	    field.addEventListener('blur', function () { finish(true); });
229	    textEl.replaceWith(field);
230	    field.focus();
231	    field.select();
232	  }
233	
234	  // [REQ-007]
235	  function editTodo(id, rawText) {
236	    var text = rawText.trim();
237	    if (text) {
238	      todos.forEach(function (t) { if (t.id === id) t.text = text; });
239	      saveTodos();
240	    }
241	    render();
242	  }
243	
244	  // [REQ-001]
245	  function deleteTodo(id) {
246	    todos = todos.filter(function (t) { return t.id !== id; });
247	    saveTodos();
248	    render();
249	  }
250	
251	  // [REQ-002] Flip completion in place; the array keeps insertion order.
252	  function toggleTodo(id) {
253	    todos.forEach(function (t) { if (t.id === id) t.completed = !t.completed; });
254	    saveTodos();
255	    render();
256	  }
257	
258	  var todos = loadTodos();
259	
260	  filterButtons.forEach(function (btn) {
261	    btn.addEventListener('click', function () {
262	      currentFilter = btn.dataset.filter;
263	      render();
264	    });
265	  });
266	
267	  // [REQ-007]
268	  searchInput.addEventListener('input', function () {
269	    searchTerm = searchInput.value;
270	    render();
271	  });
272	
273	  form.addEventListener('submit', function (e) {
274	    e.preventDefault();
275	    addTodo(input.value, dueInput.value, priorityInput.value);
276	    input.value = '';
277	    dueInput.value = '';
278	    priorityInput.value = 'med';
279	    input.focus();
280	  });
281	
282	  // [REQ-003] Recompute overdue state when the page regains focus, in case the local date has changed.
283	  window.addEventListener('focus', render);
284	
285	  render();
286	</script>
287	</body>
288	</html>
