python3 - <<'EOF'
p='index.html'; s=open(p).read()
def rep(a,b):
    global s
    assert s.count(a)==1, a
    s=s.replace(a,b)
rep("""  .priority { flex""", """  /* [REQ-009] Bulk action bar below the list. */
  .bulk { display: flex; gap: .5rem; margin-top: 1rem; }
  .priority { flex""")
rep("""  <ul data-testid="todo-list"></ul>
""", """  <ul data-testid="todo-list"></ul>
  <div class="bulk" role="group" aria-label="Bulk actions">
    <button data-testid="bulk-mark-all" type="button">Mark all complete</button>
    <button data-testid="bulk-clear-completed" type="button">Clear completed</button>
  </div>
""")
rep("""  var searchTerm = '';
""", """  var searchTerm = '';
  var markAllButton = document.querySelector('[data-testid="bulk-mark-all"]');
  var clearCompletedButton = document.querySelector('[data-testid="bulk-clear-completed"]');
""")
rep("""  var todos = loadTodos();
""", """  // [REQ-009] Mark every todo complete, ignoring the current filter and search.
  // Only the completed flag changes; the array keeps insertion order, so render() reorders per DEC-003/DEC-007/DEC-008.
  function markAllComplete() {
    todos.forEach(function (t) { t.completed = true; });
    saveTodos();
    render();
  }

  // [REQ-009] Remove every completed todo, ignoring the current filter and search. Filtering keeps the remaining insertion order.
  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos();
    render();
  }

  var todos = loadTodos();

  // [REQ-009]
  markAllButton.addEventListener('click', markAllComplete);
  clearCompletedButton.addEventListener('click', clearCompleted);
""")
open(p,'w').write(s)
EOF
sed -n '/<script>/,/<\/script>/p' index.html | sed '1d;$d' > "$TMPDIR/x.js" 2>/dev/null; node --check "$TMPDIR/x.js" && echo ok
